export type DrawerState = 'open' | 'closed';
type Listener<T> = (value: T) => void;

type Subscription<T> = {
  listener: Listener<T>;
  owner?: Listener<T>;
};

class ListenerCollection<T> {
  private readonly subscriptions: Subscription<T>[] = [];
  private notifying?: Listener<T>;

  subscribe(listener: Listener<T>): () => void {
    const subscription: Subscription<T> = { listener, owner: this.notifying };
    this.subscriptions.push(subscription);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const matches = (candidate: Subscription<T>): boolean =>
        candidate === subscription ||
        (subscription.owner !== undefined && candidate.owner === subscription.owner);
      for (let index = this.subscriptions.length - 1; index >= 0; index--) {
        if (matches(this.subscriptions[index])) this.subscriptions.splice(index, 1);
      }
    };
  }

  emit(value: T): void {
    const snapshot = [...this.subscriptions];
    for (const subscription of snapshot) {
      const previous = this.notifying;
      this.notifying = subscription.listener;
      try {
        subscription.listener(value);
      } finally {
        this.notifying = previous;
      }
    }
  }
}

export class DrawerService {
  private current: DrawerState = 'closed';
  private readonly listeners = new ListenerCollection<DrawerState>();
  get state(): DrawerState { return this.current; }
  set(state: DrawerState): void {
    if (state === this.current) return;
    this.current = state;
    this.listeners.emit(state);
  }
  toggle(): void {
    this.set(this.current === 'closed' ? 'open' : 'closed');
  }
  subscribe(listener: Listener<DrawerState>): () => void {
    return this.listeners.subscribe(listener);
  }
}

export class FilterPanelController {
  private readonly dismissListeners = new ListenerCollection<boolean>();
  constructor(private readonly drawer: DrawerService) {}
  onDismiss(listener: Listener<boolean>): () => void {
    return this.dismissListeners.subscribe(listener);
  }
  dismiss(): void {
    this.dismissListeners.emit(false);
  }
  toggleDrawer(): void {
    this.drawer.toggle();
  }
}

