import { DrawerService, FilterPanelController } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }

const drawer = new DrawerService();
equal(drawer.state, 'closed', 'drawer begins closed');
drawer.set('closed');
equal(drawer.state, 'closed', 'setting same state is harmless with no listeners');

const events: string[] = [];
let unsubscribeSecond: () => void = () => {};
let unsubscribeLate: () => void = () => {};
const unsubscribeFirst = drawer.subscribe(state => {
  events.push(`first:${state}`);
  unsubscribeSecond();
  unsubscribeLate = drawer.subscribe(next => events.push(`late:${next}`));
});
unsubscribeSecond = drawer.subscribe(state => events.push(`second:${state}`));
drawer.toggle();
deepEqual(events, ['first:open', 'second:open'], 'notifications use insertion-order snapshot');
equal(drawer.state, 'open', 'toggle opens');
drawer.set('open');
deepEqual(events, ['first:open', 'second:open'], 'unchanged state does not notify');
drawer.toggle();
deepEqual(events, ['first:open', 'second:open', 'first:closed', 'late:closed'], 'subscription changes affect later notification');
unsubscribeFirst();
unsubscribeFirst();
unsubscribeLate();
unsubscribeLate();
drawer.set('open');
deepEqual(events, ['first:open', 'second:open', 'first:closed', 'late:closed'], 'unsubscribe is idempotent');

const controller = new FilterPanelController(drawer);
const dismissals: string[] = [];
let removeB: () => void = () => {};
let removeC: () => void = () => {};
const removeA = controller.onDismiss(value => {
  dismissals.push(`a:${value}`);
  removeB();
  removeC = controller.onDismiss(next => dismissals.push(`c:${next}`));
});
removeB = controller.onDismiss(value => dismissals.push(`b:${value}`));
const beforeDismiss = drawer.state;
controller.dismiss();
deepEqual(dismissals, ['a:true', 'b:true'], 'dismiss listeners use snapshot and insertion order');
equal(drawer.state, beforeDismiss, 'dismiss does not alter drawer');
controller.dismiss();
deepEqual(dismissals, ['a:true', 'b:true', 'a:true', 'c:true'], 'dismiss subscription changes apply later');
removeA();
removeA();
removeC();
removeC();
controller.dismiss();
deepEqual(dismissals, ['a:true', 'b:true', 'a:true', 'c:true'], 'dismiss unsubscribe idempotent');
const stateBeforeToggle = drawer.state;
controller.toggleDrawer();
equal(drawer.state, stateBeforeToggle === 'open' ? 'closed' : 'open', 'controller delegates toggle');

new FilterPanelController(new DrawerService()).dismiss();

